đăng ký 04/2026; ngành chính in ấn; điểm bản đồ ghi Photo-VPP Quỳnh Nhi, cần đối chiếu có cùng cửa hàng. MST gốc dạng 8335731214-001; nhập 13 số không dấu nối."},{"district":"Huyện Tam Bình","name":"Photocopy - VPP Nhân Lan","address_line":"Khu vực xã Song Phú cũ, huyện Tam Bình (Plus Code 4W82+PC9)","category":"van_phong_pham","phone":null,"tax_code":null,"source_key":"directory:localleads:nhanlan-songphu:4w82pc9","source_url":"https://localleads.io.vn/danh-sach/print-shop/vinh-long","verification_note":"Địa điểm danh bạ có nhãn photocopy/VPP, chưa có số nhà, điện thoại, chưa ghé; cần xác nhận quầy VPP."},{"district":"Huyện Tam Bình","name":"Công ty TM DV Gia Phúc Tam Bình (đầu mối)","address_line":"20 tổ 4, ấp 3, xã Tam Bình cũ, huyện Tam Bình","category":"van_phong_pham","phone":null,"tax_code":"1501161899","source_key":"tax:1501161899:giaphuc-tambinh","source_url":"https://xinvoice.vn/mst/1501161899-cong-ty-tnhh-mtv-thuong-mai-dich-vu-gia-phuc-tam-binh","verification_note":"Hồ sơ doanh nghiệp có mã 4761 bán lẻ sách/VPP nhưng mảng hoạt động khác gồm bao bì/in ấn; CHƯA chứng minh cửa hàng VPP bán lẻ."},{"district":"Huyện Tam Bình","name":"Công ty Thiết bị Văn phòng CTB (đầu mối)","address_line":"Thửa 286, tờ bản đồ 20, tổ 15, ấp 3, xã Tam Bình cũ, huyện Tam Bình","category":"van_phong_pham","phone":null,"tax_code":"1501161659","source_key":"dauthau:1501161659:ctb-tambinh","source_url":"https://dauthau.asia/businesslistings/detail/CONG-TY-TNHH-MTV-THIET-BI-VAN-PHONG-CTB-216036/","verification_note":"Nhà thầu thiết bị văn phòng có đăng ký ngành bán lẻ sách/VPP; không có bằng chứng quầy bán lẻ, chỉ tạo lead cần gọi kiểm tra."},{"district":"Huyện Bình Tân","name":"Hộ kinh doanh Phương Anh (ngành sách-VPP)","address_line":"Tổ 1, khóm Thành Tâm, khu vực thị trấn Tân Quới cũ, huyện Bình Tân","category":"van_phong_pham","phone":null,"tax_code":null,"source_key":"tax:094185014321:phuonganh-tanquoi","source_url":"https://thongtincongty.vn/ma-so-thue/094185014321-ho-kinh-doanh-phuong-anh-to-1-khom-thanh-tam-559287262","verification_note":"Mã ngành CHÍNH bán lẻ sách-VPP; hồ sơ thuế dùng mã 12 số nên không ghi vào tax_code khi DB chỉ nhận 10/13 số. Địa danh mới Tân Quới, cần xác minh khóm cũ và tên biển hiệu."},{"district":"Huyện Bình Tân","name":"Hộ kinh doanh Tâm Hiếu (tạp hóa-VPP)","address_line":"05 ấp Tân Hạnh, xã Tân Quới cũ, huyện Bình Tân","category":"van_phong_pham","phone":null,"tax_code":"8033566162","source_key":"dauthau:8033566162:tam-hieu-tanquoi","source_url":"https://dauthau.asia/businesslistings/detail/Ho-kinh-doanh-Tam-Hieu-107016/","verification_note":"Hồ sơ nhà thầu liệt kê tạp hóa, VPP, photocopy và vật tư nông nghiệp; CHƯA xác minh quầy VPP bán lẻ hiện còn hoạt động."},{"district":"Huyện Bình Tân","name":"Công ty Trường Thịnh Bình Tân (đầu mối sách-VPP)","address_line":"1937 tổ 17, khóm Tân Lợi, thị trấn Tân Quới cũ, huyện Bình Tân","category":"van_phong_pham","phone":null,"tax_code":"1501120331","source_key":"tax:1501120331:truongthinh-binh-tan","source_url":"https://thuvienphapluat.vn/ma-so-thue/cong-ty-tnhh-truong-thinh-binh-tan-mst-1501120331.html","verification_note":"Hồ sơ đăng ký có bán BUÔN sách, báo, VPP; chưa chứng minh bán lẻ tại địa chỉ, gọi trước khi ghé."},{"district":"Huyện Bình Tân","name":"Văn phòng phẩm - Photocopy Phương Đông","address_line":"Khu vực xã Mỹ Thuận cũ, huyện Bình Tân","category":"van_phong_pham","phone":"0987900580","tax_code":null,"source_key":"directory:vido:phuongdong-mythuan","source_url":"https://mayphotocopyvido.com/tiem-photocopy-mau-trang-den-o-vinh-long-gia-re-chat-luong/","verification_note":"Bài địa phương năm 2026 nêu VPP-photocopy tại Mỹ Thuận và số điện thoại; không có số nhà, cần xác minh."},{"district":"Huyện Bình Tân","name":"Hộ kinh doanh Võ Thế Hiệp (ngành sách-VPP)","address_line":"Ấp Mỹ Tú, xã Mỹ Thuận cũ, huyện Bình Tân","category":"van_phong_pham","phone":null,"tax_code":"1801314264","source_key":"directory:thongtindoanhnghiep:vothehiep-mytu","source_url":"https://thongtindoanhnghiep.co/tim-kiem?kwd=%22L%C3%AA+H%E1%BB%93ng%22&location=vinh-long","verification_note":"Hồ sơ doanh nghiệp khoảng năm 2013 ghi ngành chính bán lẻ sách-VPP; dữ liệu CŨ, không có biển hiệu/điện thoại/tình trạng năm 2026. Chỉ điểm cần xác minh, chưa khẳng định đang bán."}]'::jsonb) AS x (
 district text, name text, address_line text, category text, phone text, tax_code text,
 source_key text, source_url text, verification_note text )
), ins AS (
 INSERT INTO public.field_prospects(
 id,area_visit_id,owner_sub,name,address_line,province,district,category,
 phone,tax_code,note,status,source_kind,research_source_key,research_source_url,research_batch)
 SELECT
 (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
 NULL,'ef943de4-18f7-49ef-8340-eefb18855534',
 s.name,s.address_line,'Vĩnh Long',s.district,s.category,s.phone,s.tax_code,
 'Nguồn công khai 21/11/2026; CHƯA GHÉ; GPS chưa xác minh; hoạt động bán lẻ chưa xác minh thực địa. '
   ||s.verification_note||' Nguồn: '||s.source_url,
 'new','manual',s.source_key,s.source_url,'2026-11-21-vinh-long-old-wave-02-three-districts'
 FROM src s
 WHERE s.district IN ('Thị xã Bình Minh','Huyện Bình Tân','Huyện Tam Bình')
  AND s.source_url LIKE 'https://%'
  AND NOT EXISTS (
   SELECT 1 FROM public.customers c WHERE c.province='Vĩnh Long' AND c.district=s.district
   AND (lower(btrim(c.name))=lower(btrim(s.name)) OR (c.phone IS NOT NULL AND s.phone IS NOT NULL AND c.phone=s.phone))
  )
  AND NOT EXISTS (
   SELECT 1 FROM public.field_prospects p WHERE p.province='Vĩnh Long' AND p.district=s.district
   AND (p.research_source_key=s.source_key
    OR (lower(btrim(p.name))=lower(btrim(s.name)) AND lower(btrim(p.address_line))=lower(btrim(s.address_line)))
    OR (p.phone IS NOT NULL AND s.phone IS NOT NULL AND p.phone=s.phone)
    OR (p.tax_code IS NOT NULL AND s.tax_code IS NOT NULL AND p.tax_code=s.tax_code))
  )
 ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING district,name,category,phone,tax_code
)
SELECT district,count(*)::int AS inserted,
 count(*) FILTER(WHERE category='nha_sach')::int AS bookstores,
 count(*) FILTER(WHERE category='van_phong_pham')::int AS stationery,
 count(*) FILTER(WHERE phone IS NOT NULL)::int AS phones,
 count(*) FILTER(WHERE tax_code IS NOT NULL)::int AS tax_codes
 FROM ins GROUP BY district ORDER BY district;
